bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
docker inspect "$cid" --format 'user={{.Config.User}} state={{.State.Status}} image={{.Image}} restarts={{.RestartCount}}'
docker exec -i -w /opt/videobot "$cid" node --input-type=module - <<'JS'
import pg from 'pg';
import {readFileSync} from 'node:fs';
const u=process.env.CREATEVDOBOT_TERMS_URL??'';
const valid=/^https:\/\/[A-Za-z0-9.-]+\/[A-Za-z0-9/_-]+\.html$/.test(u);
console.log(JSON.stringify({termsConfigured:!!u,termsValidSyntax:valid,termsUrl:valid?u:null,termsMatchesCanonical:u==='https://tgtumbler-docs.pages.dev/createvdobot-terms.html',ownerJobs:process.env.VIDEOBOT_OWNER_JOBS==='YES'}));
const p=new pg.Pool({host:process.env.VIDEOBOT_DB_HOST,user:process.env.VIDEOBOT_DB_USER,database:process.env.VIDEOBOT_DB_NAME,password:readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1,connectionTimeoutMillis:5000});
try {
 const q=await p.query("SELECT status,count(*)::integer AS n FROM videobot_owner_update_jobs GROUP BY status ORDER BY status");
 console.log('OWNER_JOB_COUNTS '+JSON.stringify(q.rows));
 const v=await p.query("SELECT status,count(*)::integer AS n FROM videobot_webhook_updates GROUP BY status ORDER BY status");
 console.log('UPDATE_COUNTS '+JSON.stringify(v.rows));
} finally {await p.end();}
JS
stage="$HOME/.local/share/gace-create-videobot/opus-8f374cc-stage-20261125"
stat -c '%a %n' "$stage/merged/src" "$stage/merged/src/runtime" "$stage/merged/src/telegram" "$stage/merged/src/runtime/creatorPollingMain.mjs"
docker image inspect create-videobot:opus-8f374cc-stage --format 'candidate_user={{.Config.User}}'
docker run --rm --network none --entrypoint sh create-videobot:opus-8f374cc-stage -c 'id; ls -ld /opt/videobot/src /opt/videobot/src/runtime /opt/videobot/src/runtime/config.mjs; test -r /opt/videobot/src/runtime/config.mjs && echo CONFIG_READABLE || echo CONFIG_UNREADABLE'
